func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXForwardedProto)); scheme != "" {
		return scheme
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXForwardedProtocol)); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXUrlScheme)); scheme != "" {
		return scheme
	}
	return "http"
}

// schemeFromHeader returns the first valid HTTP scheme (`http` or `https`) found in the
// given header value. Header values set by proxies may contain a comma separated list of
// schemes (when multiple proxies are chained) and values that are not valid HTTP schemes,
// which must be ignored so that the caller can fall back to the next source of information.
func schemeFromHeader(value string) string {
	for _, v := range strings.Split(value, ",") {
		v = strings.TrimSpace(v)
		if strings.EqualFold(v, "http") || strings.EqualFold(v, "https") {
			return v
		}
	}
	return ""
}

